{
  "summary": "The reader has an undergraduate computer science education: asymptotic analysis, algorithms (including divide and conquer, sorting, and the basic idea of fast multiplication), basic Turing machines, and the supporting mathematics of linear algebra, discrete math, probability-free basics, and complex numbers. They have not studied the FFT in depth, algebraic complexity, polynomial rings modulo relations, number theory beyond modular arithmetic and CRT basics, or numerical error analysis, and they know nothing of the research literature on fast multiplication.",
  "known": [
    {
      "name": "Linear algebra basics",
      "aliases": ["vectors", "matrices", "linear maps", "rank", "invertible matrix", "tensor-free linear algebra"],
      "gloss": "Vectors, matrices, matrix products, invertibility, subspaces, linear independence and rank over the rationals or reals."
    },
    {
      "name": "Modular arithmetic",
      "aliases": ["congruences", "mod n", "residues", "remainder"],
      "gloss": "Arithmetic on integers modulo m, including congruence, residues and the fact that coprime moduli behave independently."
    },
    {
      "name": "Prime numbers and coprimality",
      "aliases": ["primes", "gcd", "coprime", "relatively prime", "prime number theorem"],
      "gloss": "Primes, greatest common divisors, coprime integers, and the fact that primes of size about k are plentiful and findable."
    },
    {
      "name": "Binary representation and radix expansion",
      "aliases": ["base 2", "bits", "radix 2^b", "binary digits", "positional notation"],
      "gloss": "Writing nonnegative integers as sums of digits times powers of a base, with bit operations such as shifts."
    },
    {
      "name": "Schoolbook multiplication and carries",
      "aliases": ["long multiplication", "quadratic multiplication", "carry propagation", "O(n^2) multiplication"],
      "gloss": "The grade-school algorithm for multiplying integers digit by digit with carries, taking quadratic time."
    },
    {
      "name": "Divide and conquer and recurrences",
      "aliases": ["recurrence relations", "master theorem", "recursion", "Karatsuba"],
      "gloss": "Solving a problem by splitting it into smaller subproblems and bounding the cost with a recurrence."
    },
    {
      "name": "Sorting and its cost",
      "aliases": ["sort", "permuting data", "comparison sort", "O(n log n) sorting"],
      "gloss": "Rearranging records into a given order, and the n log n cost of doing so."
    },
    {
      "name": "Logarithms and exponentials",
      "aliases": ["lg", "log base 2", "log log", "iterated logarithm"],
      "gloss": "Base-2 and natural logarithms and exponentials, including lg n and lg lg n as they appear in running times."
    },
    {
      "name": "Cartesian product and mixed-radix indexing",
      "aliases": ["multi-dimensional array", "tensor index", "row-major order", "axes of an array"],
      "gloss": "Indexing an array by tuples of coordinates, one per axis, and flattening to a linear address."
    },
    {
      "name": "Cyclic groups and roots of unity",
      "aliases": ["Z/mZ", "cyclic group", "additive group of integers mod m"],
      "gloss": "The group of residues modulo m under addition, and its use for cyclic indexing and wraparound."
    },
    {
      "name": "Euclidean norm and unit disk",
      "aliases": ["modulus", "absolute value of complex number", "unit disk", "norm", "triangle inequality"],
      "gloss": "The length of a vector or complex number, the closed disk of modulus at most 1, and the triangle inequality."
    },
    {
      "name": "Fixed-point and rounding arithmetic",
      "aliases": ["truncation", "rounding error", "floor and ceiling", "dyadic rationals"],
      "gloss": "Representing numbers as integer multiples of a power of 2, rounding to the nearest grid value, and bounding the resulting absolute error."
    },
    {
      "name": "Proof by induction and summation",
      "aliases": ["geometric series", "induction", "telescoping sums"],
      "gloss": "Standard proof technique and sum formulas used to bound costs level by level in recursion."
    },
    {
      "name": "Subsets, indicator vectors and set intersection",
      "aliases": ["characteristic vector", "binomial coefficient", "k-element subsets"],
      "gloss": "Subsets of a finite set encoded as 0/1 vectors, with sizes counted by binomial coefficients."
    },
    {
      "name": "Permutation matrices",
      "aliases": ["permutations", "partial permutation", "bijection"],
      "gloss": "A rearrangement of coordinates represented as a matrix with a single one in each row and column."
    },
    {
      "name": "Euler's formula and trigonometry",
      "aliases": ["e^{i theta}", "cos and sin", "pi"],
      "gloss": "The identity e^{i theta} = cos theta + i sin theta, used to write roots of unity and phases."
    },
    {
      "name": "Gaussian function",
      "aliases": ["Gaussian", "bell curve", "e^{-x^2}"],
      "gloss": "The function exp(-x^2) as a rapidly decaying weight."
    },
    {
      "name": "Big-endian bit strings and Boolean operations",
      "aliases": ["XOR", "bitwise exclusive or", "bit position"],
      "gloss": "Bit strings and the exclusive-or operation, which is addition modulo 2."
    },
    {
      "name": "Rational numbers and field arithmetic",
      "aliases": ["Q", "rational field", "fractions"],
      "gloss": "The rationals as a field closed under addition, multiplication and division by nonzero elements."
    }
  ]
}

